+    // "YYYY-MM-DD") and never converted through Date/UTC, so they stay
+    // exactly as selected regardless of the user's time zone or travel.
+    (function () {
+      var MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July',
+        'August', 'September', 'October', 'November', 'December'];
+
+      function formatTime(value) {
+        var p = value.split(':');
