diff --git a/src/components/Modal.tsx b/src/components/Modal.tsx
new file mode 100644
index 0000000..8d4b462
--- /dev/null
+++ b/src/components/Modal.tsx
@@ -0,0 +1,51 @@
+import React, { useEffect, useRef } from 'react';
+
+interface Props {
+  onClose: () => void;
+  labelledBy: string;
+  children: React.ReactNode;
+}
+
+/**
+ * Native modal <dialog>: the browser provides the top layer, focus trapping,
+ * Escape-to-close, inert background and focus restoration to the opener.
+ * Mark the element that should receive initial focus with `data-autofocus`.
+ */
+export default function Modal({ onClose, labelledBy, children }: Props) {
+  const dialogRef = useRef<HTMLDialogElement>(null);
+
+  useEffect(() => {
+    const dialog = dialogRef.current;
+    if (!dialog) return;
+    if (!dialog.open) {
+      dialog.showModal();
+      dialog.querySelector<HTMLElement>('[data-autofocus]')?.focus();
+    }
+    return () => dialog.close();
+  }, []);
+
+  return (
+    <dialog
+      ref={dialogRef}
+      aria-labelledby={labelledBy}
+      className="relative mx-auto mt-[15vh] w-[calc(100%-2rem)] max-w-2xl overflow-visible bg-white p-0 text-inherit shadow-xl backdrop:bg-white/30 backdrop:backdrop-blur-sm"
+      onClose={onClose}
+      onClick={e => {
+        // Clicks on the backdrop target the dialog element itself
+        if (e.target === e.currentTarget) onClose();
+      }}
+    >
+      <button
+        type="button"
+        onClick={onClose}
+        aria-label="Close"
+        className="absolute -top-2 -right-2 z-10 rounded-full bg-white p-1 text-gray-500 shadow-md transition-transform hover:scale-110 hover:text-amber-400"
+      >
+        <svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
+          <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
+        </svg>
+      </button>
+      {children}
+    </dialog>
+  );
+}
