+    return false;
+  }
+  say('Passkey created.');
+  return true;
+}
+
+async function signUp(event) {
+  event.preventDefault();
+  const form = event.currentTarget;
+  const data = Object.fromEntries(new FormData(form));
+  try {
+    const res = await api.signUpFetch({ name: data.email, displayName: data.displayName });
+    if (!res.ok) {
