@@ -0,0 +1,36 @@
+const form = document.getElementById('newsletter-form');
+const status = document.getElementById('newsletter-status');
+const button = form.querySelector('button');
+
+function show(state, message) {
+  status.dataset.state = state;
+  status.textContent = message;
+}
+
+form.addEventListener('submit', async (event) => {
+  event.preventDefault();
+  if (!form.reportValidity()) return;
+
+  button.disabled = true;
+  show('pending', 'Signing you up…');
+
+  try {
+    const response = await fetch(form.action, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ email: form.elements.email.value.trim() }),
+    });
+    if (response.status === 400) {
+      show('error', 'That email address doesn’t look right. Please check it and try again.');
+      return;
+    }
+    if (!response.ok) throw new Error(`HTTP ${response.status}`);
+    form.reset();
+    show('success', 'Thanks for subscribing! Watch your inbox.');
+  } catch {
+    // Network failure, server error, or request blocked by the page's outbound policy.
+    show('error', 'Sorry, we couldn’t sign you up right now. Please try again in a moment.');
+  } finally {
+    button.disabled = false;
+  }
+});
