@@ -0,0 +1,40 @@
+(function () {
+  var form = document.getElementById('newsletter-form');
+  var message = document.getElementById('newsletter-message');
+  var button = form.querySelector('button');
+
+  function show(text, kind) {
+    message.textContent = text;
+    message.className = kind;
+  }
+
+  form.addEventListener('submit', function (event) {
+    event.preventDefault();
+    var email = form.elements.email.value.trim();
+    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
+      show('Please enter a valid email address.', 'error');
+      return;
+    }
+
+    button.disabled = true;
+    show('Signing you up…', '');
+
+    fetch('/api/subscribe', {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify({ email: email })
+    })
+      .then(function (res) {
+        if (!res.ok) throw new Error('HTTP ' + res.status);
+        form.reset();
+        show('Thanks for subscribing!', 'success');
+      })
+      .catch(function () {
+        // Network failure, server error, or request blocked by the CSP
+        show('Sorry, we couldn’t sign you up right now. Please try again later.', 'error');
+      })
+      .then(function () {
+        button.disabled = false;
+      });
+  });
+})();
