+// Static server for the homepage plus the rewards sign-up API.
+// No dependencies; run with `node server.js`.
+const http = require('http');
+const fs = require('fs');
+const path = require('path');
+const dns = require('dns').promises;
+
+const PORT = process.env.PORT || 11222;
+const SIGNUPS_FILE = path.join(__dirname, 'data', 'signups.jsonl');
+
+const EMAIL_RE = /^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]{1,64}@([A-Za-z0-9-]{1,63}(?:\.[A-Za-z0-9-]{1,63})+)$/;
+const DISPOSABLE = new Set(['mailinator.com', 'guerrillamail.com', '10minutemail.com', 'tempmail.com', 'yopmail.com', 'trashmail.com']);
+
+// Checks that an address is well-formed and that its domain can receive mail.
+// It cannot prove the customer controls the mailbox; only a message sent to it can.
+async function checkEmail(raw) {
+  const email = String(raw || '').trim();
+  if (email.length > 254) return { ok: false, reason: 'That email address is too long.' };
+  const m = EMAIL_RE.exec(email);
+  if (!m) return { ok: false, reason: 'Enter a valid email address.' };
+  const domain = m[1].toLowerCase();
+  if (DISPOSABLE.has(domain)) return { ok: false, reason: 'Disposable email addresses are not accepted.' };
+  try {
+    const mx = await dns.resolveMx(domain);
+    if (mx.length) return { ok: true, email, domain };
+  } catch (e) {
+    if (!['ENODATA', 'ENOTFOUND'].includes(e.code)) {
+      return { ok: false, reason: 'We could not check that domain right now. Please try again.', transient: true };
+    }
+  }
+  // RFC 5321 implicit MX: fall back to an address record.
+  try {
+    const addrs = await dns.resolve4(domain).catch(() => dns.resolve6(domain));
+    if (addrs.length) return { ok: true, email, domain };
+  } catch (e) { /* fall through */ }
+  return { ok: false, reason: `${domain} doesn't appear to accept email.` };
+}
+
+function readJson(req) {
+  return new Promise((resolve, reject) => {
+    let body = '';
+    req.on('data', (c) => {
+      body += c;
+      if (body.length > 10_000) { reject(new Error('too large')); req.destroy(); }
+    });
+    req.on('end', () => { try { resolve(JSON.parse(body || '{}')); } catch (e) { reject(e); } });
+    req.on('error', reject);
+  });
+}
+
+function send(res, status, obj) {
+  res.writeHead(status, { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' });
+  res.end(JSON.stringify(obj));
+}
+
+http.createServer(async (req, res) => {
+  const url = new URL(req.url, 'http://localhost');
+  if (req.method === 'POST' && (url.pathname === '/api/verify-email' || url.pathname === '/api/register')) {
+    let data;
+    try { data = await readJson(req); } catch (e) { return send(res, 400, { ok: false, reason: 'Invalid request.' }); }
+    const result = await checkEmail(data.email);
+    if (url.pathname === '/api/verify-email') return send(res, result.transient ? 503 : 200, result);
+    // Registration re-checks server-side; never trust the browser's earlier result.
+    const name = String(data.name || '').trim().slice(0, 100);
+    if (!name) return send(res, 400, { ok: false, reason: 'Please enter your name.' });
+    if (!result.ok) return send(res, result.transient ? 503 : 400, result);
+    fs.mkdirSync(path.dirname(SIGNUPS_FILE), { recursive: true });
+    fs.appendFileSync(SIGNUPS_FILE, JSON.stringify({ name, email: result.email, at: new Date().toISOString() }) + '\n');
+    return send(res, 201, { ok: true });
+  }
+  if (req.method === 'GET' && (url.pathname === '/' || url.pathname === '/index.html')) {
+    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
+    return fs.createReadStream(path.join(__dirname, 'index.html')).pipe(res);
+  }
+  res.writeHead(404, { 'Content-Type': 'text/plain' });
+  res.end('Not found');
+}).listen(PORT, () => console.log(`Daily Grind on :${PORT}`));

